INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT156-S2-Q17$batch08$, 156, 2, 17, $batch08$Must Be True$batch08$, $batch08$To measure a small boat hull accurately, it is necessary to level the hull so that a baseline can be established. This does not require sophisticated tools, but it does require a leveling tool called a “line level.” When scientists discovered a small ninth-century boat, they wanted to record the dimensions of its hull accurately. None of the scientists, however, had any experience measuring hulls. Because of this they were not sure they had leveled the hull before establishing a baseline.$batch08$, $batch08$If the statements above are true, then which one of the following must also be true?$batch08$, $batch08$D$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q17$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$The scientists did not accurately measure the hull’s dimensions because they had no experience measuring hulls.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$The scientists accurately determined the hull’s dimensions, provided that they leveled the hull.$batch08$, $batch08$Reversed$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$If the scientists did not accurately determine the hull’s dimensions, it was because they did not have a line level.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$The scientists were able to accurately record the hull’s dimensions only if they used a line level.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$If the scientists had measured the hull’s dimensions accurately, then at least one of them would have had experience measuring hulls.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Accurately measuring a hull requires leveling it. Leveling requires a line level. The scientists weren't sure they had leveled the hull.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Chain the requirements: accurate measurement → leveled → used a line level. So an accurate measurement requires a line level. Notice what we *don't* know: whether they leveled it or measured accurately.$batch08$), (2, $batch08$Goal$batch08$, $batch08$They measured accurately only if they used a line level.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$They weren't *sure* they leveled it. They might have. We can't conclude the measurement was wrong.$batch08$), ($batch08$B$batch08$, $batch08$Leveling is required for accuracy, not enough for it. They could level the hull and still measure badly.$batch08$), ($batch08$C$batch08$, $batch08$A missing line level is one way to fail, not the only one. They could have had one and still erred.$batch08$), ($batch08$D$batch08$, $batch08$Accurate → leveled → line level. "Only if" states the requirement.$batch08$), ($batch08$E$batch08$, $batch08$Experience is never said to be required. Inexperienced people could get lucky and level it correctly.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT156-S2-Q17$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
